346		Success   bool        `json:"success"`
347		Data      interface{} `json:"data,omitempty"`
348		Total     int         `json:"total,omitempty"`
349		Message   string      `json:"message,omitempty"`
350		Error     string      `json:"error,omitempty"`
351		Timestamp string      `json:"timestamp"`
352	}
