929	// GetSupervisorAgentStatus handles GET /api/dve/{nodeId}/supervisor-agent/status
930	// Returns the current health status of the KNIRVAGENT supervisor for this DVE.
931	// If the node exists but no agent is running yet, it attempts to start one (lazy provisioning).
932	func (h *DVEHandlers) GetSupervisorAgentStatus(w http.ResponseWriter, r *http.Request) {
933		w.Header().Set("Content-Type", "application/json")
934	
935		if h.knirvagentManager == nil {
936			json.NewEncoder(w).Encode(map[string]interface{}{
937				"status": "unavailable",
938				"error":  "KNIRVAGENT supervisor not configured",
939			})
940			return
941		}
942	
943		nodeID := mux.Vars(r)["nodeId"]
944	
945		// Lazy-provision: if no agent is running for THIS specific DVE, start one.
946		// Check per-DVE socket — not just "any agent running" — so that accessing a
947		// second DVE while a first DVE's agent is active still triggers provisioning.
948		if _, sockErr := h.knirvagentManager.GetSocketPathForDVE(nodeID); sockErr != nil && h.dveManager != nil && nodeID != "" {
949			if node, err := h.dveManager.GetNode(nodeID); err == nil && node != nil {
950				log.Printf("[DVE] Lazy-provisioning KNIRVAGENT for node %s (%s)", nodeID, node.Name)
951				startCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
952				defer cancel()
953				if err := h.knirvagentManager.StartAgent(startCtx, nodeID, 30*time.Second); err != nil {
954					log.Printf("[DVE] Lazy-provisioning failed for node %s: %v", nodeID, err)
955				}
956			}
957		}
958	
959		// Check per-DVE status
960		status := "offline"
961		if _, err := h.knirvagentManager.GetSocketPathForDVE(nodeID); err == nil {
962			status = "online"
963		} else if h.knirvagentManager.IsRunning() {
964			status = "initializing"
965		}
966		running := status != "offline"
967	
968		healthErr := h.knirvagentManager.HealthCheck(context.Background())
969		healthStatus := "healthy"
970		if healthErr != nil {
971			healthStatus = "unhealthy"
972		}
973		// Override health if we just provisioned (socket might not be ready yet)
974		if status == "initializing" {
975			healthStatus = "booting"
976		}
977	
978		json.NewEncoder(w).Encode(map[string]interface{}{
979			"status":        status,
980			"health":        healthStatus,
981			"running":       running,
982			"base_url":      h.knirvagentManager.GetBaseURL(),
983			"agent_type":    "knirvagent",
984			"role":          "supervisor",
985			"node_id":       nodeID,
986			"timestamp":     getCurrentTimestamp(),
987		})
988	}
989	
990	// GetSupervisorAgentSession handles GET /api/dve/{nodeId}/supervisor-agent/session
991	// Returns a WebSocket URL for real-time communication with the KNIRVAGENT supervisor.
992	// If the node exists but no agent is running, attempts lazy provisioning first.
993	func (h *DVEHandlers) GetSupervisorAgentSession(w http.ResponseWriter, r *http.Request) {
994		w.Header().Set("Content-Type", "application/json")
995	
996		nodeID := mux.Vars(r)["nodeId"]
997	
998		if h.knirvagentManager == nil {
999			w.WriteHeader(http.StatusServiceUnavailable)
1000			json.NewEncoder(w).Encode(map[string]interface{}{
1001				"error": "KNIRVAGENT supervisor not configured",
1002			})
1003			return
1004		}
1005	
1006		// Lazy-provision if no agent is running for THIS specific DVE (regardless of
1007		// whether agents for other DVEs are already running).
1008		if _, sockErr := h.knirvagentManager.GetSocketPathForDVE(nodeID); sockErr != nil && h.dveManager != nil && nodeID != "" {
1009			if node, err := h.dveManager.GetNode(nodeID); err == nil && node != nil {
1010				log.Printf("[DVE] Lazy-provisioning KNIRVAGENT for session on node %s (%s)", nodeID, node.Name)
1011				startCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
1012				defer cancel()
1013				if err := h.knirvagentManager.StartAgent(startCtx, nodeID, 30*time.Second); err != nil {
1014					log.Printf("[DVE] Lazy-provisioning failed for session on node %s: %v", nodeID, err)
1015				}
1016			}
1017		}
1018	
1019		// Verify the agent socket exists for this specific DVE (covers both
1020		// "never started" and "failed to provision" cases).
1021		if _, err := h.knirvagentManager.GetSocketPathForDVE(nodeID); err != nil {
1022			w.WriteHeader(http.StatusServiceUnavailable)
1023			json.NewEncoder(w).Encode(map[string]interface{}{
1024				"error": "KNIRVAGENT not available for this DVE: " + err.Error(),
1025			})
1026			return
1027		}
1028	
1029		// The session URL points to the backend WebSocket proxy which relays
1030		// I/O between the frontend terminal and the KNIRVAGENT subprocess.
1031		wsURL := fmt.Sprintf("/ws/dve/%s/agent", nodeID)
1032	
1033		json.NewEncoder(w).Encode(map[string]interface{}{
1034			"ws_url":    wsURL,
1035			"base_url":  h.knirvagentManager.GetBaseURL(),
1036			"running":   true,
1037			"timestamp": getCurrentTimestamp(),
1038		})
1039	}
1040	
1041	// RegisterRoutes registers the DVE routes with the router
1042	func (h *DVEHandlers) RegisterRoutes(r *mux.Router, authMiddleware *middleware.AuthMiddleware) {
1043		// Create a subrouter for DVE endpoints
1044		dveRouter := r.PathPrefix("/api/dve-nodes").Subrouter()
1045	
1046		// Routes with optional auth (for role-based filtering)
1047		if authMiddleware != nil {
1048			optionalAuthRouter := dveRouter.PathPrefix("").Subrouter()
1049			optionalAuthRouter.Use(authMiddleware.OptionalAuth)
1050			optionalAuthRouter.HandleFunc("", h.GetDVENodes).Methods("GET", "OPTIONS")
1051			optionalAuthRouter.HandleFunc("/{id}", h.GetDVENode).Methods("GET", "OPTIONS")
1052			optionalAuthRouter.HandleFunc("/{id}/endpoints", h.GetDVENodeEndpoints).Methods("GET", "OPTIONS")
1053			optionalAuthRouter.HandleFunc("/{id}/ssh-endpoint", h.GetDVENodeSSHEndpoint).Methods("GET", "OPTIONS")
1054			optionalAuthRouter.HandleFunc("/{id}/validation-endpoint", h.GetDVENodeValidationEndpoint).Methods("GET", "OPTIONS")
1055			optionalAuthRouter.HandleFunc("/{id}/error-resolution-endpoint", h.GetDVENodeErrorResolutionEndpoint).Methods("GET", "OPTIONS")
1056		} else {
1057			// If no auth middleware, allow public access
1058			dveRouter.HandleFunc("", h.GetDVENodes).Methods("GET", "OPTIONS")
1059			dveRouter.HandleFunc("/{id}", h.GetDVENode).Methods("GET", "OPTIONS")
1060			dveRouter.HandleFunc("/{id}/endpoints", h.GetDVENodeEndpoints).Methods("GET", "OPTIONS")
1061			dveRouter.HandleFunc("/{id}/ssh-endpoint", h.GetDVENodeSSHEndpoint).Methods("GET", "OPTIONS")
1062			dveRouter.HandleFunc("/{id}/validation-endpoint", h.GetDVENodeValidationEndpoint).Methods("GET", "OPTIONS")
1063			dveRouter.HandleFunc("/{id}/error-resolution-endpoint", h.GetDVENodeErrorResolutionEndpoint).Methods("GET", "OPTIONS")
1064		}
1065	
1066		// Protected routes for management
1067		if authMiddleware != nil {
1068			protectedDVERouter := dveRouter.PathPrefix("").Subrouter()
1069			protectedDVERouter.Use(authMiddleware.RequireAuth)
1070			protectedDVERouter.HandleFunc("", h.PostDVENodes).Methods("POST", "OPTIONS")
1071			protectedDVERouter.HandleFunc("/{id}", h.UpdateDVENode).Methods("PUT", "OPTIONS")
1072			protectedDVERouter.HandleFunc("/{id}", h.DeleteDVENode).Methods("DELETE", "OPTIONS")
1073		} else {
1074			// If no auth middleware, allow all routes (for testnet mode)
1075			dveRouter.HandleFunc("", h.PostDVENodes).Methods("POST", "OPTIONS")
1076			dveRouter.HandleFunc("/{id}", h.UpdateDVENode).Methods("PUT", "OPTIONS")
1077			dveRouter.HandleFunc("/{id}", h.DeleteDVENode).Methods("DELETE", "OPTIONS")
1078		}
1079	
1080		// /api/dve/ aliases — frontend monitor-panel and connections-panel use these paths
1081		dveAliasRouter := r.PathPrefix("/api/dve").Subrouter()
1082		dveAliasRouter.HandleFunc("/workers", h.GetDVEWorkers).Methods("GET", "OPTIONS")
1083		dveAliasRouter.HandleFunc("/{nodeId}/tasks", h.GetDVENodeTasksAlias).Methods("GET", "OPTIONS")
1084		dveAliasRouter.HandleFunc("/{nodeId}/metrics", h.GetDVENodeMetricsAlias).Methods("GET", "OPTIONS")
1085	
1086		// /api/p2p/ — P2P network topology endpoints (Gap 5)
1087		p2pRouter := r.PathPrefix("/api/p2p").Subrouter()
1088		p2pRouter.HandleFunc("/peers", h.GetP2PPeers).Methods("GET", "OPTIONS")
1089	
1090		// SSH session creation for DVE nodes — used by ConsolePanel (Gap 1)
1091		dveAliasRouter.HandleFunc("/{nodeId}/ssh-session", h.CreateNodeSSHSession).Methods("POST", "OPTIONS")
1092	
1093		// DVE Supervisor Agent (KNIRVAGENT) status and session endpoints
1094		if h.knirvagentManager != nil {
1095			dveAliasRouter.HandleFunc("/{nodeId}/supervisor-agent/status", h.GetSupervisorAgentStatus).Methods("GET", "OPTIONS")
1096			dveAliasRouter.HandleFunc("/{nodeId}/supervisor-agent/session", h.GetSupervisorAgentSession).Methods("GET", "OPTIONS")
1097		}
1098	}
