	vars := mux.Vars(r)
	creationID := vars["id"]

	creation, err := h.dveCreationService.GetDVECreation(creationID)
	if err != nil {
		h.sendError(w, "Creation not found", http.StatusNotFound)
		return
	}

	h.sendJSON(w, creation, "DVE creation retrieved successfully", http.StatusOK)
}

