12	import { apiRequest, API_BASE_URL, buildQueryString } from '@/lib/api';
13	import { webSocketService } from '@/lib/websocket-service';
14	
15	export const useDVENodes = (filter?: DVENodeFilter) => {
16	  const queryClient = useQueryClient();
17	  const queryString = buildQueryString(filter || {});
18	  const queryKey = ['dve-nodes', queryString];
19	
20	  // Fetch DVE nodes with React Query
21	  const {
22	    data: nodes = [],
23	    isLoading,
24	    error: queryError,
25	    refetch: fetchNodes
26	  } = useQuery<DVENode[]>({
27	    queryKey,
28	    queryFn: async () => {
29	      const url = `${API_BASE_URL}/api/dve-nodes${queryString}`;
30	      const response: APIResponse<DVENode[]> = await apiRequest(url, { method: 'GET' });
31	      if (response.success && Array.isArray(response.data)) {
32	        return response.data;
33	      }
34	      throw new Error(response.error || 'Failed to fetch DVE nodes');
35	    },
36	    staleTime: 30000, // 30 seconds
37	  });
38	
39	  const error = queryError instanceof Error ? queryError.message : null;
40	
41	  // WebSocket connection and real-time cache updates
42	  useEffect(() => {
43	    const handleDVENodeUpdate = (payload: any) => {
44	      queryClient.setQueryData<DVENode[]>(queryKey, (prevNodes = []) => {
45	        const existingIndex = prevNodes.findIndex(node => node.id === payload.id);
46	        if (existingIndex >= 0) {
47	          return prevNodes.map(node =>
48	            node.id === payload.id
49	              ? {
50	                  ...node,
51	                  ...payload,
